    {
      "card_ids": ["C10"],
      "claim": "Basmisanil, a very high-transfer analogue, showed approximately 75% absolute oral bioavailability in humans after tablet dosing, directly supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Linezolid, with near-maximal transfer, is reported as 100% orally bioavailable in humans by absolute oral versus parenteral comparison, strongly supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Vernakalant had an absolute oral bioavailability of 71 ± 21% in healthy volunteers after oral dosing versus IV, a direct human measurement supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Brepocitinib showed 75% absolute oral bioavailability in a human mass balance study, supporting the high-bioavailability prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Navoximod had 55.5% absolute oral bioavailability after a 200 mg oral dose compared with IV in healthy subjects, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Pimodivir, a high-transfer analogue, had approximately 46% oral bioavailability in humans, further supporting the high-bioavailability conclusion.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All retrieved high-transfer experimental analogues show human oral bioavailability values well above the 20% threshold, with multiple direct absolute bioavailability measurements ranging from ~46% to 100%. The consistent supportive evidence predicts high oral bioavailability for the query.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement is available for the query molecule itself.",
    "No retrieved analogue with comparable transferability demonstrates low oral bioavailability, so threshold-negative evidence is absent.",
    "Some records are not explicitly absolute bioavailability measurements, but the direct absolute human measurements dominate the conclusion."
  ],
